const $=s=>document.querySelector(s);const fmt=n=>n.toLocaleString('en-US');
const toys=[{id:0,name:'瑶妹',en:'YAO',series:'鹿灵心语',tone:'#f1dce6',body:'#dcaac8',accent:'#a46b9a',price:300,stock:120,image:'r4_sprite.webp',motif:'鹿角 · 粉发 · 针织小鹿',tag:'灵鹿粉'},{id:1,name:'小妲己',en:'DAJI',series:'狐焰流光',tone:'#f0dfbd',body:'#d2ad68',accent:'#a67939',price:260,stock:86,image:'r6_sprite.webp',motif:'狐耳 · 金色华服 · 蓬松狐尾',tag:'狐焰金'},{id:2,name:'香香',en:'XIANGXIANG',series:'元气出击',tone:'#e3ebc8',body:'#b9d77b',accent:'#73894b',price:320,stock:64,image:'r2_sprite.webp',motif:'双马尾 · 荧光绿 · 潮流机能',tag:'活力绿'},{id:3,name:'常小娥',en:'CHANG XIAOE',series:'月华绮梦',tone:'#e6e1f5',body:'#bbb2df',accent:'#8976b9',price:360,stock:45,image:'r3_sprite.webp',motif:'月兔 · 银发 · 月光紫',tag:'月华紫'}];
function art(t){return `<span class="character character-${t.id}"><img src="assets/${t.image}" alt="王者万象棋${t.name}形象" decoding="async"></span>`}
let heroChoice=0;function setHero(n){heroChoice=n;render()}
function fresh(){return {points:2680,level:1,logged:true,assets:[{id:0,star:1,qty:5},{id:1,star:1,qty:2},{id:2,star:2,qty:1}],claimed:false,records:[{type:'扫码',title:'CD 扫码领取',delta:500,desc:'鹿灵心语 · 第 02 批次',time:'2026.10.08 14:32',status:'已完成'},{type:'购买',title:'购买瑶妹 × 1',delta:-300,desc:'鹿灵心语 · 一星卡牌',time:'2026.10.08 13:18',status:'已完成'},{type:'扫码',title:'CD 扫码领取',delta:500,desc:'狐焰流光 · 第 01 批次',time:'2026.10.07 19:45',status:'已完成'}]}}
let state=fresh(),page='home',shopTab='cards',starFilter=0,recordFilter='全部',busy=false;const levels=['初见玩家','进阶玩家','资深藏家','星耀藏家'],costs=[0,800,1200,1800];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function go(p){if(busy)return;page=p;closeModal();render();window.scrollTo(0,0)}function closeModal(){if(busy)return;$('#overlay').innerHTML=''}
function modal(title,body){$('#overlay').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modalhead"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${body}</section></div>`;setTimeout(()=>$('#overlay button')?.focus(),30)}
function record(type,title,delta,desc,status='已完成'){state.records.unshift({type,title,delta,desc,status,time:'2026.10.08 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),id:'DEMO-'+Date.now().toString().slice(-8)})}
function summary(rows){return `<div class="summary">${rows.map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`}
function success(title,desc){render();modal('操作结果',`<div class="success"><div class="check">✓</div><h3>${title}</h3><p>${desc}</p></div><button class="primary" onclick="closeModal()">完成</button>`)}
function login(next){if(state.logged)return true;modal('登录潮玩俱乐部',`<div class="success"><div class="check">✦</div><h3>收藏，从这里开始</h3><p>体验登录后可使用扫码、购买与兑换。<br>此处为前端模拟，不连接微信账号。</p></div><button class="primary" onclick="state.logged=true;render();closeModal();${next}">模拟微信登录</button>`);return false}
function enough(n,next){if(state.points>=n)return true;modal('还差一点积分',`${summary([['本次需要',fmt(n)+' 积分'],['当前可用',fmt(state.points)+' 积分'],['还需获得',fmt(n-state.points)+' 积分']])}<p>扫描 CD 上的领取码，积攒积分后再来。</p><button class="primary" onclick="scan()">去扫码领积分</button>`);return false}
function locked(level,what){modal('解锁 '+what,`<div class="success"><div class="check">✧</div><h3>${levels[level]}专属</h3><p>达到 Lv.${level} ${levels[level]}即可使用${what}。<br>解锁后仍需支付对应积分或卡牌材料。</p></div>${summary([['当前等级','Lv.'+state.level+' '+levels[state.level]],['解锁等级','Lv.'+level+' '+levels[level]]])}<button class="primary" onclick="go('member')">查看会员与升级</button>`)}
function card(t,star=1,qty=null){return `<button class="toycard" onclick="${qty===null?'product('+t.id+')':'assetDetail('+t.id+','+star+')'}"><div class="art" style="--tone:${t.tone}"><span class="artlabel">${t.en}</span>${art(t)}<span class="cardcrest">✦</span><span class="serial">HERO / 00${t.id+1}</span></div><div class="cardinfo"><strong>${t.name}</strong><div class="stars">${'★'.repeat(star)}${'☆'.repeat(5-star)}</div><div class="cardmeta"><span>${t.series}</span><span class="price">${qty===null?fmt(t.price)+' 积分':'持有 × '+qty}</span></div></div></button>`}
function title(en,cn,desc){return `<div class="pagetitle"><div><div class="eyebrow">${en}</div><h1>${cn}</h1><p>${desc}</p></div><span class="demo">前端演示 · 测试配置</span></div>`}
function balance(){return `<section class="balance"><div class="eyebrow">MY HONOR POINTS</div><div class="number">${fmt(state.points)}<small>可用积分</small></div><div class="caption">每一次收藏，都有新的惊喜</div><div class="levelrow"><span class="leveltag">✦ Lv.${state.level} ${levels[state.level]}</span><span>${state.level===3?'已达到最高等级':'距下一等级还需消耗 '+fmt(costs[state.level+1])+' 积分'}</span></div><div class="progress"><i style="width:${state.level===3?100:Math.min(100,state.points/costs[state.level+1]*100)}%"></i></div><button class="scan" onclick="scan()">▦ 扫码领积分 ↗</button></section>`}
function home(){let ht=toys[heroChoice];return title('HONOR COLLECTION CLUB','把热爱，收入收藏。','王者皮肤灵感 × 万象棋形象，一起点亮本命。')+`<div class="homegrid"><section class="hero hero-${heroChoice}"><div class="hero-copy"><span class="pill">✦ 王者主题收藏 / VOL. 01</span><div class="hero-kicker">HEROES, IN YOUR HANDS</div><h2>你的本命英雄，<br>这次为你而来。</h2><p>收集万象棋形象卡牌，点亮星级图鉴。<br>扫码积攒积分，把峡谷的热爱收入收藏。</p><button class="primary" onclick="product(${heroChoice})">收藏 ${ht.name}　↗</button><div class="hero-switch" aria-label="切换英雄主题">${toys.slice(0,3).map((t,i)=>`<button class="${i===heroChoice?'on':''}" onclick="setHero(${i})" aria-label="切换至${t.name}"><span style="background:${t.tone}"></span>${t.tag}</button>`).join('')}</div></div><div class="heroart">${art(ht)}</div><div class="hero-sign">${ht.en}<small>${ht.name} · 王者万象棋形象</small></div><span class="hero-orbit" aria-hidden="true">✧</span></section>${balance()}</div><div class="quick">${[['✧','幸运抽奖','开启英雄惊喜','draw'],['◈','点券兑换','解锁游戏快乐','exchange'],['✦','卡牌合成','本命再升一星','synth'],['♧','会员权益','解锁收藏特权','member']].map(([i,t,s,p],n)=>`<button onclick="${p==='exchange'?"shopTab='tickets';go('shop')":p==='synth'?"openSynth()":"go('"+p+"')"}"><span class="qicon" style="background:${['#e8e5f4','#f3e8cf','#e8edde','#f0e1e9'][n]}">${i}</span><span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div><div class="lowergrid"><section><div class="sectiontitle"><h2>本期英雄精选 <small>HERO SPOTLIGHT</small></h2><button class="textbtn" onclick="go('shop')">查看图鉴 ↗</button></div><div class="cards">${toys.slice(0,3).map(t=>card(t)).join('')}</div></section><section><div class="sectiontitle"><h2>收藏家俱乐部 <small>MEMBER CLUB</small></h2></div><div class="club"><div class="eyebrow" style="color:#947743">YOUR NEXT LEVEL</div><h3>从心动收藏，<br>到星耀珍藏。</h3><p>合成你的本命英雄，解锁点券兑换。<br>每一步成长，都有新的收藏可能。</p><button onclick="go('member')">探索会员权益 ↗</button><span class="badgeart">♛</span></div></section></div><div class="notice"><b>◉ 收藏馆公告</b><span>王者主题前端预览 · 卡牌采用万象棋公开形象，主题系列为概念设计。积分、会员与兑换规则均为待确认的测试配置。</span></div>`}
function shop(){return title('HERO COLLECTION','本命英雄，等你收藏。','每一件心动，都值得被珍藏。')+`<div class="filterbar"><button class="${shopTab==='cards'?'selected':''}" onclick="shopTab='cards';render()">潮玩卡牌</button><button class="${shopTab==='tickets'?'selected':''}" onclick="shopTab='tickets';render()">王者荣耀点券 <span style="opacity:.6">Lv.2</span></button><button onclick="go('records');recordFilter='全部';render()">我的购买 / 兑换记录 ↗</button></div>${shopTab==='cards'?`<div class="shopcards">${toys.map(t=>card(t)).join('')}</div><p class="rules">王者万象棋形象收藏 · 初始一星 · 卡面主题为概念设计，库存与价格待确认</p>`:`<div class="info" style="margin-bottom:20px">Lv.2 资深藏家解锁兑换 · 测试档位与预计时效，发放渠道和资料字段待确认</div><div class="exchange">${[60,300,680].map((n,i)=>`<article class="ticket"><div class="ticketicon">◈ ${n} <small style="font-size:12px">点券</small></div><h3>王者荣耀 ${n} 点券</h3><p>Lv.2 资深藏家起 · 演示库存 50 份<br>预计 1–3 个工作日处理（待确认）</p><div class="price">${fmt([600,2800,6000][i])} 积分</div><button class="primary ${state.level<2?'locked':''}" onclick="exchange(${i})">${state.level<2?'⌑ 升级解锁':'立即兑换'}</button></article>`).join('')}</div>`}`}
function collection(){let a=state.assets.filter(a=>a.qty>0&&(!starFilter||a.star===starFilter));return title('MY HERO GALLERY','我的英雄图鉴','从一星到五星，点亮你的英雄收藏。')+`<div class="filterbar">${[0,1,2,3,4,5].map(n=>`<button class="${starFilter===n?'selected':''}" onclick="starFilter=${n};render()">${n?n+' 星':'全部收藏'}</button>`).join('')}<button onclick="openSynth()">✦ 合成升星</button></div>${a.length?`<div class="shopcards">${a.map(a=>card(toys[a.id],a.star,a.qty)).join('')}</div>`:`<div class="empty"><span>✧</span>还没有${starFilter?starFilter+' 星':''}卡牌<br><button class="primary" style="margin-top:20px" onclick="go('shop')">去收藏第一张</button></div>`}`}
function member(){return `<button class="back" onclick="go('home')">← 返回首页</button>`+title('GROW WITH YOUR COLLECTION','每一级，都有新的可能。','权益逐级继承，普通消费不会降低会员等级。')+`<div class="membergrid">${levels.map((l,i)=>`<section class="tier ${state.level===i?'current':''}"><div class="eyebrow">LEVEL 0${i}</div><h3>${['○','✧','◈','✦'][i]} ${l}</h3><span class="status">${i===state.level?'当前等级':i<state.level?'已达成':'待解锁'}</span><div class="tiercost">${i?fmt(costs[i]):'免费'} <small>${i?'升级积分':'基础等级'}</small></div><p>${['积分抽奖<br>卡牌购买','继承基础权益<br>二星 / 三星卡牌合成','继承进阶权益<br>王者荣耀点券兑换','继承全部权益<br>四星 / 五星卡牌合成'][i]}</p><button class="primary" ${i!==state.level+1?'disabled':''} onclick="upgrade()">${state.level===3&&i===3?'已达到最高等级':i<=state.level?'已解锁':i===state.level+1?'升级并解锁':'需逐级升级'}</button></section>`).join('')}</div><div class="info" style="margin-top:22px">演示等级与费用：初见 → 进阶 800 积分 → 资深 1,200 积分 → 星耀 1,800 积分。名称、费用、权益门槛及有效期待确认。本原型采用逐级升级、不降级、无到期。</div>`}
function profile(){return title('MY COLLECTION','你好，收藏家。','热爱有迹可循，惊喜正在发生。')+`<div class="profilegrid"><div>${balance()}<div class="widepanel" style="margin-top:20px"><div style="display:flex;gap:15px;align-items:center"><div class="avatar" style="width:52px;height:52px">☻</div><div><strong>${state.logged?'峡谷收藏家':'游客'}</strong><p class="rules" style="margin:5px 0">${state.logged?'用户编号 HK202600108':'登录后开启你的收藏之旅'}</p></div></div><button class="reset" onclick="state.logged=!state.logged;render();toast(state.logged?'已模拟登录':'已切换为游客，账户演示数据保留')">${state.logged?'体验退出登录':'模拟微信登录'}</button></div></div><div class="widepanel menulist">${[['♧ 会员中心','member'],['↗ 积分明细','points'],['▤ 全部业务记录','records'],['✧ 我的卡牌','collection']].map(([s,p])=>`<button onclick="go('${p}')"><span>${s}</span><span>→</span></button>`).join('')}<button onclick="support()"><span>☏ 联系客服</span><span>→</span></button><button onclick="rules()"><span>ⓘ 玩法与演示说明</span><span>→</span></button><button onclick="resetDemo()"><span>↺ 重置演示体验</span><span>→</span></button></div></div>`}
function records(points=false){let rr=state.records.filter(r=>points?r.delta!==0:recordFilter==='全部'||r.type===recordFilter);return `<button class="back" onclick="go('profile')">← 返回我的</button>`+title(points?'POINTS HISTORY':'MY ACTIVITY',points?'积分明细':'我的业务记录',points?'每一笔收入与支出，都清晰可见。':'查看购买、合成、升级与兑换进度。')+(points?'':`<div class="filterbar">${['全部','扫码','购买','抽奖','合成','升级','兑换'].map(t=>`<button class="${recordFilter===t?'selected':''}" onclick="recordFilter='${t}';render()">${t}</button>`).join('')}</div>`)+`<div class="widepanel">${rr.length?rr.map(r=>`<div class="record"><div><strong>${r.title}</strong><p>${escapeHTML(r.desc)}</p><p>${r.time} · ${r.id||'DEMO-260108'}</p>${!points?`<span class="status">${r.status}</span>`:''}${r.type==='兑换'?` <button class="textbtn" onclick="orderDetail('${r.id}')">查看进度 →</button>`:''}</div><div style="text-align:right"><div class="delta">${r.delta>0?'+':''}${r.delta||'—'}</div><p>${r.delta?'积分':'卡牌变动'}</p></div></div>`).join(''):`<div class="empty"><span>▤</span>暂无${recordFilter==='全部'?'':recordFilter}记录，新的故事等你开启。</div>`}</div>`}
function draw(){return `<button class="back" onclick="go('home')">← 返回首页</button>`+title('A LITTLE LUCK, A BIG SURPRISE','今日的幸运，等你开启。','每一次抽奖，都是一份小小的期待。')+`<div class="drawlayout"><div class="drawboard"><div class="prizegrid">${['500 积分','瑶妹 ×1','100 积分','小妲己 ×1','center','50 积分','香香 ×1','200 积分','20 积分'].map((p,i)=>i===4?`<button class="prize drawcenter" onclick="drawConfirm()">开启惊喜<small>100 积分 / 次</small></button>`:`<div class="prize" id="prize${i}"><span>${[1,3,6].includes(i)?'♧':'✧'}</span>${p}</div>`).join('')}</div><p style="text-align:center;font-size:11px;color:#8b72a9">可用积分 ${fmt(state.points)} · 测试奖池</p></div><div class="widepanel rules"><h3>惊喜清单与概率</h3><p>500 积分 5% · 瑶妹 10% · 100 积分 20%<br>小妲己 10% · 50 积分 20% · 香香 10%<br>200 积分 10% · 20 积分 15%</p><h3>参与说明</h3><p>基础等级即可参与，每次消耗 100 积分。<br>本原型模拟奖池与抽奖动画，奖品直接记入演示账户。正式奖品、概率、库存及次数限制待确认。</p><button class="textbtn" onclick="recordFilter='抽奖';go('records')">查看抽奖记录 ↗</button></div></div>`}
function render(){const active=['home','shop','collection','profile'].includes(page)?page:['member','points','records'].includes(page)?'profile':'home';$('#app').innerHTML=`<header><div class="brand"><i>✳</i><div>荣耀藏馆<small>王者主题 · 积分收藏</small></div></div><nav class="topnav">${[['home','首页'],['shop','积分商城'],['collection','我的卡牌'],['profile','我的']].map(([p,n])=>`<button class="${p===active?'active':''}" onclick="go('${p}')">${n}</button>`).join('')}</nav><button class="userchip textbtn" onclick="go('profile')"><div class="avatar">☻</div><span>${state.logged?'峡谷收藏家':'游客 · 登录'}　⌄</span></button></header><main>${({home,shop,collection,member,profile,records,points:()=>records(true),draw})[page]()}</main><footer><span>荣耀藏馆 © 2026 · COLLECT YOUR HEROES</span><span>前端交互原型 · 所有业务配置待确认</span></footer><nav class="bottomnav" aria-label="主导航">${[['home','⌂','首页'],['shop','▧','商城'],['collection','♧','卡牌'],['profile','☻','我的']].map(([p,i,n])=>`<button class="${p===active?'active':''}" onclick="go('${p}')"><span>${i}</span>${n}</button>`).join('')}</nav>`}
function scan(){if(!login('scan()'))return;modal('扫码领积分',`<div class="scanframe">▦</div><p>扫描 CD 包装上的专属二维码，领取收藏积分。<br>本原型不调用摄像头，请选择扫码结果体验。</p><div class="scanoptions"><button onclick="claim('valid')">有效码 +500</button><button onclick="claim('used')">已领取</button><button onclick="claim('expired')">已过期</button><button onclick="claim('invalid')">无效码</button><button onclick="claim('network')">网络异常</button></div><button class="primary" onclick="claim('valid')">模拟扫描 CD 领取码</button>`)}
function claim(type){if(type==='valid'&&state.claimed)type='used';if(type!=='valid'){const msg={used:'这个领取码已使用，每件 CD 的专属码只能领取一次。',expired:'这个领取码已过期，请联系官方客服。',invalid:'未识别到有效的 CD 领取码，请检查后重新扫描。',network:'网络连接中断，本次未领取积分，请重试。'};modal('扫码提示',`<p>${msg[type]}</p><button class="primary" onclick="scan()">${type==='network'?'重试扫码':'重新扫码'}</button><button class="textbtn" style="width:100%;margin-top:15px" onclick="support()">联系客服</button>`);return}state.claimed=true;state.points+=500;record('扫码','CD 扫码领取',500,'鹿灵心语 · 演示唯一领取码');success('+500 积分','领取成功！当前可用 '+fmt(state.points)+' 积分。')}
let productQty=1;function product(id){productQty=1;showProduct(id)}function showProduct(id){let t=toys[id];modal('收藏 '+t.name,`<div class="art" style="--tone:${t.tone}">${art(t)}</div><p>王者万象棋 · ${t.name}形象卡牌<br>${t.motif} · ${t.series}概念主题<br>初始一星 · 演示库存 ${t.stock} 份 · 测试价格</p><div class="qty"><span>购买数量</span><button onclick="productQty=Math.max(1,productQty-1);showProduct(${id})" aria-label="减少数量">−</button><strong>${productQty}</strong><button onclick="productQty=Math.min(10,productQty+1);showProduct(${id})" aria-label="增加数量">＋</button></div>${summary([['获得卡牌',t.name+' × '+productQty],['消耗积分',fmt(t.price*productQty)],['操作后余额',fmt(Math.max(0,state.points-t.price*productQty))+' 积分']])}<button class="primary" onclick="buy(${id})">${state.points<t.price*productQty?'积分不足 · 去扫码':'确认购买 · '+fmt(t.price*productQty)+' 积分'}</button>`)}
function addAsset(id,star,qty){let a=state.assets.find(a=>a.id===id&&a.star===star);if(a)a.qty+=qty;else state.assets.push({id,star,qty})}
function buy(id){if(!login('product('+id+')'))return;let t=toys[id],n=t.price*productQty;if(!enough(n))return;if(t.stock<productQty){toast('库存不足，请减少数量');return}state.points-=n;t.stock-=productQty;addAsset(id,1,productQty);record('购买','购买'+t.name+' × '+productQty,-n,t.series+' · 一星卡牌');success('收藏成功',t.name+' × '+productQty+' 已加入你的卡牌收藏。')}
function upgrade(){if(!login("go('member')"))return;let target=state.level+1,n=costs[target];if(!n)return;if(!enough(n))return;modal('确认会员升级',`<p>升级后永久保留已达等级（演示配置）。权益解锁后仍需支付对应使用成本。</p>${summary([['当前等级','Lv.'+state.level+' '+levels[state.level]],['升级至','Lv.'+target+' '+levels[target]],['消耗积分',fmt(n)],['升级后余额',fmt(state.points-n)+' 积分'],['新增权益',target===1?'二星 / 三星合成':target===2?'王者荣耀点券兑换':'四星 / 五星合成']])}<button class="primary" onclick="confirmUpgrade(${target})">确认升级</button>`)}
function confirmUpgrade(target){if(target!==state.level+1||!enough(costs[target]))return;state.points-=costs[target];state.level=target;record('升级','升级至 '+levels[target],-costs[target],'Lv.'+(target-1)+' → Lv.'+target);success('升级成功','欢迎成为'+levels[target]+'，新的权益已解锁。')}
function assetDetail(id,star){let t=toys[id],a=state.assets.find(a=>a.id===id&&a.star===star);modal(t.name+' · '+star+' 星',`<div class="art" style="--tone:${t.tone}">${art(t)}</div><p>${t.series} · 持有 ${a.qty} 张<br>${star===5?'已达到最高星级，珍藏你的五星光芒。':'将 3 张同名同星卡牌合成为下一星级（演示配方）。'}</p>${star<5?`<button class="primary" onclick="synth(${id},${star+1})">合成至 ${star+1} 星</button>`:'<button class="primary" onclick="closeModal()">已达到最高星级</button>'}`)}
function openSynth(){if(!login('openSynth()'))return;if(state.level<1){locked(1,'卡牌合成');return}modal('选择合成目标',`<p>演示配方：3 张同名同星 → 1 张下一星级，确定成功，无额外积分费用。</p><label for="synthtoy">目标卡牌</label><select id="synthtoy">${toys.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select><label for="synthstar">目标星级</label><select id="synthstar">${[2,3,4,5].map(n=>`<option value="${n}">${n} 星 · Lv.${n<4?1:3} 解锁</option>`).join('')}</select><button class="primary" onclick="synth(Number($('#synthtoy').value),Number($('#synthstar').value))">查看合成配方</button>`)}
function synth(id,target){if(!login('openSynth()'))return;let required=target<4?1:3;if(state.level<required){locked(required,target+' 星合成');return}let a=state.assets.find(a=>a.id===id&&a.star===target-1),qty=a?.qty||0;modal('合成 '+toys[id].name+' · '+target+' 星',`<div class="material"><div class="miniart">${art(toys[id])}</div><div><strong>${toys[id].name} · ${target-1} 星 × 3</strong><small>持有 ${qty} 张 ${qty<3?'· 还缺 '+(3-qty)+' 张':'· 材料充足'}</small></div></div>${summary([['获得卡牌',toys[id].name+' · '+target+' 星 × 1'],['消耗材料','同名 '+(target-1)+' 星卡牌 × 3'],['剩余材料',Math.max(0,qty-3)+' 张'],['附加积分','0 积分'],['合成结果','确定成功（测试配方）']])}<button class="primary" ${qty<3?'disabled':''} onclick="confirmSynth(${id},${target})">${qty<3?'材料不足':'确认合成'}</button>${qty<3?'<button class="textbtn" style="width:100%;margin-top:15px" onclick="go(\'shop\')">去商城补充卡牌 →</button>':''}`)}
function confirmSynth(id,target){let a=state.assets.find(a=>a.id===id&&a.star===target-1);if(!a||a.qty<3||state.level<(target<4?1:3))return;a.qty-=3;addAsset(id,target,1);record('合成',toys[id].name+'合成至 '+target+' 星',0,'消耗 '+(target-1)+' 星 ×3，获得 '+target+' 星 ×1');success('升星成功',toys[id].name+' · '+target+' 星已加入收藏。')}
function drawConfirm(){if(!login('drawConfirm()')||!enough(100))return;modal('开启一次幸运抽奖',`${summary([['本次获得','测试奖池中的随机奖品'],['消耗积分','100 积分'],['抽奖后余额',fmt(state.points-100)+' 积分']])}<p>演示奖池概率见抽奖页面。前端随机结果仅用于交互展示。</p><button class="primary" onclick="drawRun()">确认抽奖</button>`)}
function drawRun(){if(busy||state.points<100)return;closeModal();state.points-=100;busy=true;const slots=[0,1,2,3,5,6,7,8],weights=[5,10,20,10,20,10,10,15];let r=Math.random()*100,ix=0;for(let i=0;i<weights.length;i++){r-=weights[i];if(r<0){ix=i;break}}let ticks=0;const timer=setInterval(()=>{$$('.prize.active').forEach(e=>e.classList.remove('active'));$('#prize'+slots[ticks%8])?.classList.add('active');ticks++;if(ticks>=16+ix+1){clearInterval(timer);busy=false;let labels=['500 积分','瑶妹 ×1','100 积分','小妲己 ×1','50 积分','香香 ×1','200 积分','20 积分'],points=[500,0,100,0,50,0,200,20];record('抽奖','积分抽奖',-100,'单次抽奖 · 演示奖池');if(points[ix]){state.points+=points[ix];record('抽奖','抽奖奖励 '+labels[ix],points[ix],'奖品已入账')}else{addAsset({1:0,3:1,5:2}[ix],1,1);record('抽奖','抽奖奖励 '+labels[ix],0,'卡牌已加入收藏')}success('获得 '+labels[ix],'惊喜已加入演示账户，当前积分 '+fmt(state.points)+'。')}},90)}const $$=s=>document.querySelectorAll(s);
function exchange(i){if(!login('exchange('+i+')'))return;if(state.level<2){locked(2,'点券兑换');return}let n=[600,2800,6000][i];if(!enough(n))return;modal('兑换 '+[60,300,680][i]+' 点券',`<p>演示资料字段，实际字段按发放渠道确认。预计 1–3 个工作日处理（待确认）。</p><label for="server">游戏区服</label><select id="server"><option>微信 · iOS</option><option>微信 · Android</option><option>QQ · iOS</option><option>QQ · Android</option></select><label for="account">游戏账号标识</label><input id="account" placeholder="输入演示账号标识" maxlength="40"><div class="info" style="margin-top:15px">请勿填写账号密码。本原型不会发送资料或发放真实点券。</div><button class="primary" onclick="exchangeConfirm(${i})">下一步 · 核对兑换信息</button>`)}
let pendingExchange;function escapeHTML(v){return v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function exchangeConfirm(i){let account=$('#account').value.trim();if(account.length<3){toast('请填写至少 3 个字符的演示账号标识');$('#account').focus();return}pendingExchange={i,server:$('#server').value,account};let n=[600,2800,6000][i];modal('确认兑换订单',`${summary([['兑换内容',[60,300,680][i]+' 点券'],['游戏区服',escapeHTML(pendingExchange.server)],['账号标识',escapeHTML(account)],['消耗积分',fmt(n)],['兑换后余额',fmt(state.points-n)+' 积分'],['预计处理时间','1–3 个工作日（测试）']])}<p>请仔细核对资料。提交后生成演示订单，不会发放真实点券。</p><button class="primary" onclick="exchangeSubmit()">确认资料并提交</button>`)}
function exchangeSubmit(){if(!pendingExchange)return;const {i,account,server}=pendingExchange,n=[600,2800,6000][i];if(state.level<2||!enough(n))return;pendingExchange=null;state.points-=n;record('兑换','王者荣耀 '+[60,300,680][i]+' 点券',-n,server+' · '+account,'待处理');render();modal('订单提交成功',`<div class="success"><div class="check">✓</div><h3>已进入处理队列</h3><p>演示订单已创建，积分已扣除。<br>可在业务记录中体验履约进度。</p></div><button class="primary" onclick="recordFilter='兑换';go('records')">查看兑换订单</button>`)}
function orderDetail(id){let r=state.records.find(r=>r.id===id);if(!r)return;modal('兑换订单进度',`${summary([['订单编号',r.id],['兑换内容',r.title],['兑换资料',escapeHTML(r.desc)],['当前状态',r.status],['积分费用',fmt(-r.delta)]])}<p>提交成功 → 待处理 → 处理中 → 已完成<br>无法履约时可关闭并退款。以下仅用于前端状态演示。</p><div class="scanoptions">${['待处理','处理中','已完成','人工核查'].map(s=>`<button ${r.status==='已关闭并退款'?'disabled':''} onclick="orderState('${id}','${s}')">${s}</button>`).join('')}<button ${r.status==='已关闭并退款'||r.status==='已完成'?'disabled':''} onclick="refund('${id}')">关闭并退款</button></div><button class="primary" onclick="support()">联系客服</button>`)}
function orderState(id,s){let r=state.records.find(r=>r.id===id);if(r.status==='已关闭并退款')return;r.status=s;render();orderDetail(id)}function refund(id){let r=state.records.find(r=>r.id===id);if(['已关闭并退款','已完成'].includes(r.status))return;r.status='已关闭并退款';state.points-=r.delta;record('退款','兑换订单退款',-r.delta,r.id+' · 演示无法履约');render();orderDetail(id)}
function support(){modal('联系俱乐部客服',`<div class="success"><div class="check">☏</div><h3>我们在这里</h3><p>客服渠道与服务时间待运营确认。<br>正式版本将在这里提供真实的联系入口。</p></div><div class="info">遇到兑换异常，请保留订单编号；不需要提供游戏账号密码。</div><button class="primary" onclick="closeModal()">知道了</button>`)}function rules(){modal('关于本次体验',`<p>荣耀藏馆 · 王者主题收藏 · 前端 H5 交互原型</p><p>角色视觉参考王者万象棋官网公开素材。鹿灵心语、狐焰流光等为本原型卡面主题命名，并非官方皮肤名称；最终角色及皮肤以授权素材包为准。</p><div class="info">全部资产只在当前页面内存中模拟，刷新即可恢复初始状态。无后台、无真实登录、无摄像头扫码、无真实点券发放。</div><p>演示配置：扫码 +500 积分；抽奖 100 积分 / 次；合成 3 张同名同星卡牌 → 下一星级卡牌，确定成功，免费。<br>卡牌购买、点券兑换、会员升级费用，以及库存、概率、资料字段、处理时效均待确认。</p><button class="primary" onclick="closeModal()">开始探索</button>`)}function resetDemo(){modal('重置演示体验',`<p>将积分、会员等级、卡牌与记录恢复为初始演示状态。</p><button class="primary" onclick="state=fresh();toys.forEach((t,i)=>t.stock=[120,86,64,45][i]);page='home';closeModal();render();toast('演示体验已重置')">确认重置</button>`)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});render();
